fn solve(a: i8, b: i8) -> (i8, i8) {
    // Number of different-type pair days is the minimum of the two counts.
    let different_type_days = a.min(b);

    // Compute absolute difference and then integer-divide by 2 for same-type days.
    let diff = (a - b).abs();
    let same_type_days = diff / 2;

    (different_type_days, same_type_days)
}

fn main() {
    // Example tests
    assert_eq!(solve(5, 3), (3, 1)); // 3 days of different-type, (5-3)/2 = 1 same-type
    assert_eq!(solve(3, 5), (3, 1)); // symmetric case
    assert_eq!(solve(7, 7), (7, 0)); // all days are different-type, no same-type
    println!("All tests passed!");
}